effect.shader:
const int MAX_OCTAVES = 8;

float hash21(vec2 p) {
    p = fract(p * vec2(127.1, 311.7));
    p += dot(p, p + 34.23);
    return fract(p.x * p.y);
}

float valueNoise(vec2 p) {
    vec2 cell = floor(p);
    vec2 f = fract(p);
    vec2 w = f * f * (3.0 - 2.0 * f);
    float a = hash21(cell);
    float b = hash21(cell + vec2(1.0, 0.0));
    float c = hash21(cell + vec2(0.0, 1.0));
    float d = hash21(cell + vec2(1.0, 1.0));
    return mix(mix(a, b, w.x), mix(c, d, w.x), w.y);
}

float fbm(vec2 p, int levels) {
    float sum = 0.0;
    float amplitude = 1.0;
    float norm = 0.0;
    for (int i = 0; i < MAX_OCTAVES; i++) {
        if (i >= levels) break;
        sum += valueNoise(p) * amplitude;
        norm += amplitude;
        p *= 2.0;
        amplitude *= 0.5;
    }
    return sum / max(norm, 0.0001);
}

void main() {
    int levels = clamp(int(octaves + 0.5), 1, MAX_OCTAVES);

    vec2 p = acScreenNorm * vec2(acAspect, 1.0) / max(scale, 0.01) * 12.0 + vec2(evolution);
    vec2 shift = vec2(
        fbm(p, levels) - 0.5,
        fbm(p + vec2(19.3, 7.7), levels) - 0.5
    ) * border * acEscalaDePixel * acTexelSize * 2.0;

    // Empurrar a amostragem e depois cortar o alfa de novo é o que rasga a
    // borda. No meio da camada o alfa já é 1, então o empurrão não aparece — o
    // efeito se concentra sozinho onde existe transição.
    vec4 color = texture(inputImg, clamp(acScreenNorm + shift, 0.0, 1.0));
    float alpha = smoothstep(0.5 - sharpness, 0.5 + sharpness, color.a);

    fragColor = vec4(color.rgb, alpha);
}
